            function GVfpPodani(parentContent, options) {
                const def0 = $.Deferred();
                var l_ixsPri = options.ixs_pri;
                var l_soutez = options.soutez;
                var l_acAg = options.ac_ag;
                var por_cis_nab = null;
                if (options.allDok && !options.novyDT) {
                    var dlg = Gordic.Pap.Dialogs.GPapDotazPodani(parentContent, { ixs_pri: options.ixs_pri, ixp: options.ixp, ac_ag: options.ac_ag, agenda: "vfp", soutez: options.soutez, ixs_esu: options.ixs_esu, ixp_den: null }, Gordic.Gin.Globals.Enums.ModOtevreni.showWindow)
                        .then(function (retVal) {
                        if (retVal) {
                            l_ixsPri = retVal.ixs_pri;
                            l_soutez = retVal.soutez;
                            l_acAg = retVal.ac_ag;
                        }
                        else {
                            l_ixsPri = null;
                        }
                        def0.resolve();
                    });
                }
                else
                    def0.resolve();
                return def0.then(function () {
                    if (l_ixsPri) {
                        const defEsu = $.Deferred();
                        if (options.ixs_esu != "" && options.ixs_esu != null) {
                            Gordic.Pap.Dialogs.GPapVyberPorCisNab(parentContent, { ixs_pri: l_ixsPri, agenda: "vfp", ixs_esu: options.ixs_esu }, Gordic.Gin.Globals.Enums.ModOtevreni.showWindow)
                                .then(function (retVal) {
                                if (retVal == null)
                                    defEsu.reject().promise();
                                else {
                                    por_cis_nab = retVal.por_cis_nab;
                                    defEsu.resolve(retVal.por_cis_nab);
                                }
                            })
                                .fail(function () { defEsu.reject().promise(); });
                        }
                        else
                            defEsu.resolve(-1);
                        return defEsu.then(function (por_cis_nab) {
                            return Gordic.Pap.Dialogs.GPapVyberUkon(parentContent, { ixs_pri: l_ixsPri, agenda: "vfp", ixs_esu: options.ixs_esu, soutez: l_soutez, por_cis_nab: por_cis_nab }, Gordic.Gin.Globals.Enums.ModOtevreni.showWindow).then(function (retVal) {
                                if (retVal == null) {
                                    return $.Deferred().reject().promise();
                                }
                                else
                                    return $.Deferred().resolve(retVal).promise();
                            });
                        })
                            .fail(function () { return $.Deferred().reject().promise(); });
                    }
                    else {
                        if (!options.novyDT) {
                            parentContent.dialogs.warning("jres:26600276", "jres:26600315"); //RC 26600315 : Nebyl vybrán případ pro provedení operace!
                            return $.Deferred().reject().promise();
                        }
                        else
                            return $.Deferred().resolve({ ixs_krk: "0000ASK0A1IB", ktg_typ: options.ktg_typ }).promise();
                    }
                }).then(function (retval) {
                    var l_obj = {};
                    l_obj.ele = options.ele;
                    l_obj.ixs_krk = retval.ixs_krk;
                    l_obj.ktg_typ = retval.ktg_typ;
                    l_obj.ixs_pri = l_ixsPri;
                    l_obj.soutez = l_soutez;
                    l_obj.por_cis_nab = por_cis_nab;
                    l_obj.ac_ag = l_acAg;
                    if (!options.ele) {
                        var l_generuj = options.genIxp;
                        if (options.ktg_typ == 2081 || options.ktg_typ == 2085)
                            l_generuj = true;
                        if (Gordic.Eko.Utils.GetEkoUserSettingsPidSejmuti(parentContent, l_generuj ? "ano" : "ne") === "1") {
                            parentContent.beginOperation("Založení nového dokumentu: Vložte PID", 0, 1);
                            return Gordic.Wfl.Dialogs.GenerovaniIxp(parentContent, {
                                TypDok: Gordic.Wfl.Globals.Enums.TypDok.Cizi,
                                TypId: Gordic.Wfl.Globals.Enums.TypId.IXP,
                                DotazPriExistenciVJineAgende: true,
                                HlaseniPriExistenciVAgende: false,
                                ZpusobGenerovani: Gordic.Wfl.Globals.Enums.ZpusobGenerovaniIxp.ParametremGinGenIxp,
                            }, Gordic.Gin.Globals.Enums.ModOtevreni.showModalWindow)
                                .then(function (retVal, content) {
                                if (retVal != null && !retVal.IxpExist) {
                                    //that.progressOperation("Založení nové smlouvy - Hotovo", 1);
                                    if (retVal && retVal.Ixp) {
                                        l_obj.ixp = retVal.Ixp;
                                    }
                                    else {
                                        l_obj.ixp = "";
                                    }
                                }
                                else if (retVal != null) {
                                    //that.progressOperation("Otevírání existujícího dokladu", 1);
                                    l_obj.ixp = retVal.Ixp;
                                }
                                return $.Deferred().resolve(l_obj);
                            })
                                .always(function () {
                                parentContent.endOperation();
                            });
                        }
                        else
                            return $.Deferred().resolve(l_obj).promise();
                    }
                    else
                        return $.Deferred().resolve(l_obj).promise();
                }).then(function (l_obj) {
                    return parentContent.isl.VfpDetailDT.insert(l_obj).getData();
                });
            }
