                //---------------------------------------------------------------------
                createKpiCount(poradi, label, hodnota) {
                    return new GObservableObject({
                        name: poradi.toString(),
                        value: hodnota.toString(),
                        primaryText: label,
                        secondaryText: "",
                        visible: true,
                        // action: new GAction({ name: "countAkce" + poradi.toString(), run: function () {} })
                    });
                }
                //---------------------------------------------------------------------
                createKpiSeparator(poradi) {
                    return new GObservableObject({
                        name: poradi.toString(),
                        value: "",
                        primaryText: "",
                        secondaryText: "",
                        visible: true,
                        // action: new GAction({ name: "countAkce" + poradi.toString(), run: function () {} })
                    });
                }
                //---------------------------------------------------------------------
                nactiDetail(ixs_pri) {
                    if (!this.Kontrolapristupu())
                        return;
                    var that = this;
                    that.isl.VfpDotacniTitul.read({
                        data: { ixs_pri: ixs_pri },
                        fragments: ["common", "detail", "minimum", "foreach"]
                    })
                        .getData()
                        .then(function (detail) {
                        var newGpc = Gordic.Eko.Utils.createBookGpc(that.gpc, detail.ixp_den);
                        var detailContent = that.navigate(["Gordic.Vfp.WebClient.GVfpDetailDT", {
                                gridRemoteControl: null,
                                gpc: newGpc
                            }], {
                            taskId: "actGVfpSeznamScr",
                            uid: "GVfpDetailDT#",
                            data: detail
                        });
                        detailContent.on("close", function (ev, ctx) {
                            if (ev.target === detailContent.get(0) && ctx && ctx.isChanged) {
                                that.load();
                            }
                        });
                    });
                }
                //---------------------------------------------------------------------
                naplnStrukturuPri() {
                    var seznam = [];
                    if (this.data.prehled.length > 0) {
                        for (var i = 0, I = this.data.hist.length; i < I; i++) {
                            var l_zaznam = {};
                            l_zaznam.ixs_pri = this.data.hist[i].ixs_pri;
                            seznam.push(l_zaznam);
                        }
                    }
                    return seznam;
                }
                //---------------------------------------------------------------------
                nactiSeznamBezFin(id) {
                    if (!this.Kontrolapristupu())
                        return;
                    var that = this;
                    var filtr = {};
                    if (id == 2) {
                        filtr.pole = "bez_financovani";
                        filtr.oper = "=";
                        filtr.hodnota = "";
                    }
                    else if (id == 4) {
                        filtr.pole = "bez_nasmlouvanosti";
                        filtr.oper = "=";
                        filtr.hodnota = "";
                    }
                    else if (id == 6) {
                        filtr.pole = "bez_rezervaci";
                        filtr.oper = "=";
                        filtr.hodnota = "";
                    }
                    var newGpc = Gordic.Eko.Utils.createBookGpc(this.gpc, "*rok"); //Gordic.Eko.GEkoBookVariant.year
                    var seznamContent = this.navigate(["Gordic.Vfp.WebClient.GVfpSeznam", { gpc: newGpc }], {
                        taskId: "actGVfpSeznamScr",
                        uid: "GVfpSeznam#",
                        filtr: filtr
                    });
                    seznamContent.on("close", function (ev, ctx) {
                        if (ev.target === seznamContent.get(0) && ctx && ctx.isChanged) {
                            that.load();
                        }
                    });
                }
                //---------------------------------------------------------------------
                nactiSeznam(id, kniha) {
                    if (!this.Kontrolapristupu())
                        return;
                    var that = this;
                    var filtr = {};
                    switch (id) {
                        case 1:
                            filtr.pole = "s_dgr";
                            filtr.hodnota = "20,00"; //20,0
                            filtr.oper = "in";
                            break;
                        case 2:
                            filtr.pole = "s_dgr";
                            filtr.hodnota = "10";
                            filtr.oper = "=";
                            break;
                        case 3:
                            filtr.pole = "s_dgr";
                            filtr.hodnota = "50";
                            filtr.oper = "=";
                            break;
                        case 4:
                            filtr.pole = "c";
                            filtr.hodnota = this.limitDashBoard1.toString();
                            filtr.oper = "<";
                            break;
                        case 5:
                            filtr.pole = "c";
                            filtr.hodnota = (this.limitDashBoard1 + 1).toString() + "," + this.limitDashBoard3.toString();
                            filtr.oper = "<>";
                            break;
                        case 6:
                            filtr.pole = "c";
                            filtr.hodnota = (this.limitDashBoard3 + 1).toString() + "," + this.limitDashBoard4.toString();
                            filtr.oper = "<>";
                            break;
                        case 7:
                            filtr.pole = "c";
                            filtr.hodnota = this.limitDashBoard4.toString();
                            filtr.oper = ">";
                            break;
                    }
                    var newGpc = Gordic.Eko.Utils.createBookGpc(this.gpc, kniha);
                    var seznamContent = this.navigate(["Gordic.Vfp.WebClient.GVfpSeznam", { gpc: newGpc }], {
                        taskId: "actGVfpSeznamScr",
                        uid: "GVfpSeznam#",
                        filtr: filtr
                    });
                    seznamContent.on("close", function (ev, ctx) {
                        if (ev.target === seznamContent.get(0) && ctx && ctx.isChanged) {
                            that.load();
                        }
                    });
                }
                //---------------------------------------------------------------------
                Kontrolapristupu() {
                    if (this.paramSulPri == "0") {
                        this.dialogs.warning("jres:26600870"); //RC 26600870 : Nemáte právo na prohlížení případů.
                        return false;
                    }
                    return true;
                }
