                akceUkonceni() {
                    var that = this;
                    var otazka = "jres:26600479"; //RC 26600479 : Opravdu chcete ukončit DT?;;Po ukončení budou znemožněny jakékoliv manipulace s případem!
                    this.dotaz(otazka)
                        .then(() => {
                        var odp = [0, 0, 0];
                        var stru = {
                            seznam: that.vratData(), akce: "ukonceni", param: 200, odpoved: odp
                        };
                        that.isl.PapUkonceni.ukonceni(stru).get().then(function (retVal) {
                            var def = $.Deferred();
                            if (retVal.data.dotaz != "") { // dotaz, co dělat když jsou nenavázané prostředky
                                var def0 = $.Deferred();
                                that.dotaz(retVal.data.dotaz)
                                    .then(() => {
                                    stru.odpoved[0] = 1;
                                    that.isl.PapUkonceni.ukonceni(stru).get().then(function (retVal) {
                                        var def1 = $.Deferred();
                                        if (retVal.data.dotaz != "") { // dotaz, zda uvolnit prostředky
                                            that.dotaz(retVal.data.dotaz)
                                                .then(() => {
                                                stru.odpoved[1] = 1;
                                                that.dotaz(retVal.data.hlas) // dotaz zda upravit částku
                                                    .then(() => {
                                                    stru.odpoved[2] = 1;
                                                    def1.resolve();
                                                })
                                                    .fail(() => {
                                                    stru.odpoved[2] = -1;
                                                    def1.resolve();
                                                });
                                            })
                                                .fail(() => {
                                                stru.odpoved[1] = -1;
                                                def1.resolve();
                                            });
                                        }
                                        def1.then(function () {
                                            that.isl.PapUkonceni.ukonceni(stru).get().then(function (retVal) {
                                                def0.resolve(retVal.data);
                                            });
                                        });
                                    });
                                })
                                    .fail(function () { def0.reject(); }); // nepokračuji - nanavázané prostředky
                                def0.then(function (retVal) {
                                    def.resolve(retVal);
                                });
                                def0.fail(function () { def.reject(); });
                            }
                            else
                                def.resolve(retVal.data);
                            def.then(function (retVal) {
                                if (retVal.hlas != "") {
                                    that.dialogs.warning("jres:26600276", retVal.hlas); //RC 26600276 : Upozornění
                                }
                                if (retVal.ok) {
                                    that.isChanged = true;
                                    that.NactiData();
                                }
                            });
                        });
                    });
                }
                //---------------------------------------------------------------------
                akceUkonceniZrusit() {
                    var that = this;
                    var otazka = "jres:26600480"; //RC 26600480 : Opravdu chcete zrušit ukončení DT?;;Po zrušení ukončení bude opět zpřístupněna manipulace s případem!
                    this.dotaz(otazka)
                        .then(() => {
                        var stru = {
                            seznam: this.vratData(), akce: "odukonceni", param: 200
                        };
                        that.isl.PapUkonceni.ukonceni(stru).get().then(function (retVal) {
                            if (retVal.data.hlas != "") {
                                that.dialogs.warning("jres:26600276", retVal.data.hlas); //RC 26600276 : Upozornění
                            }
                            if (retVal.data.ok) {
                                that.isChanged = true;
                                that.NactiData();
                            }
                        });
                    });
                }
