                storno() {
                    var that = this;
                    var l_hlas = "";
                    var l_param = "";
                    var l_title = "";
                    var def = $.Deferred();
                    if (this.data.pidDto.vfp_stav != 90) //storno
                     {
                        that.isl.VfpDetailDT.kontrolaPredStornem({ ixp: this.data.pidDto.ixp }).get()
                            .then(function (retVal) {
                            if (retVal.hlas != "") {
                                if (retVal.hlas)
                                    l_hlas = retVal.hlas;
                            }
                            def.resolve();
                        });
                    }
                    else
                        def.resolve();
                    def.then(function () {
                        if (that.data.pidDto.vfp_stav == 90) {
                            l_hlas = "jres:26600418"; //RC 26600418 : Opravdu chcete provést STORNO STORNA dokumentu?
                            l_param = "storno storna";
                            l_title = "jres:26600930"; //RC 26600930 : Důvod zrušení storna
                            that.data.parametry.akce = "stornoStornaUkon";
                        }
                        else {
                            l_hlas += that.data.parametry.nadTyp2 === 103 /*KTGTYP_nad_main_z*/ ? "jres:26600420" : "jres:26600419"; //RC 26600420 : Opravdu chcete provést STORNO dokumentu a tím i celého Dotačního titulu?
                            //RC 26600488 : Opravdu chcete provést STORNO dokumentu a tím i celé Veřejné zakázky?
                            l_param = "storno";
                            l_title = "jres:26600429"; //RC 26600429 : Důvod storna
                            that.data.parametry.akce = "stornoUkon";
                        }
                        that.dotaz("jres:26600399", l_hlas)
                            .then(() => {
                            var dlg = Gordic.Pap.Dialogs.GPapObecnyInput(that, { titulek: l_title, label: "jres:26600430", povinne: true, agenda: "vfp", typ: "string", input: "" } //RC 26600430 : Důvod
                            , Gordic.Gin.Globals.Enums.ModOtevreni.showWindow)
                                .then(function (retVal) {
                                that.data.parametry.duvodStorno = retVal.navrat;
                                that.saveData(l_param);
                            })
                                .fail(function () {
                                that.dialogs.warning("jres:26600276", "jres:26600431"); //RC 26600431 : Storno nebylo provedeno v důsledku nevyplnění důvodu.
                            });
                            //}
                            //else
                            //    def.resolve();
                            //def.then(function () {
                            //})
                        });
                    });
                }
