                    this.actions.schProstAkce.update({ enabled: this.data.prava.up_c_real && !this.modPU });
                    this.actions.odSchvaleniAkce.update({ enabled: this.data.prava.odschvaleni && !this.modPU });
                    this.actions.stornoAkce.update({ enabled: this.data.prava.storno && !this.modPU });
                    this.actions.financovaniAkce.update({ enabled: this.data.prava.financovani && !this.modPU });
                    this.actions.okrAkce.update({ enabled: this.data.prava.okr && !this.modPU });
                    this.actions.pzaDTAkce.update({ enabled: this.data.prava.pza && !this.modPU });
