                    this.actions.prevzetiAkce.update({ enabled: this.data.prava.prevzeti && !this.modPU });
                    this.actions.prideleniAkce.update({ enabled: this.data.prava.prideleni && !this.modPU });
                    this.actions.vlozspisnetAkce.update({ enabled: this.data.prava.vlozspisnet && !this.modPU });
                    this.actions.vlozspisZadAkce.update({ enabled: this.data.prava.vlozspisnet && !this.modPU });
                    this.actions.schvalprocAkce.update({ enabled: this.data.prava.schvalproc && !this.modPU });
                    this.actions.vraceniDokladuDoWflAkce.update({ enabled: this.data.prava.vracenidokladudowfl && !this.modPU });
