                        this.findForms("FormFin").gform("hasChanged") ||
                        this.findForms("FormKomentar").gform("hasChanged");
                    if (!zmena) {
                        switch (this.data.parametry.nadTyp1) {
                            case 1: /*KTGTYP_nad_main*/
                            case 3: /*KTGTYP_nad_sou*/
                                zmena = this.findForms("Form03").gform("hasChanged") || this.findForms("Form04").gform("hasChanged");
                                break;
                            case 4: /*KTGTYP_nad_esu*/
                                zmena = this.findForms("FormProjekt").gform("hasChanged") ||
                                    this.findForms("FormPopisZadatele").gform("hasChanged") ||
                                    this.findForms("FormVyuctovani").gform("hasChanged") ||
                                    this.findForms("FormDoplUdaje").gform("hasChanged") ||
                                    this.findForms("FormFinancovani").gform("hasChanged") ||
                                    this.findForms("FormHodnoceni").gform("hasChanged") ||
                                    this.findForms("FormProjekt").gform("hasChanged") ||
                                    this.findForms("FormSubjekt").gform("hasChanged");
                                break;
                            case 5: /*KTGTYP_nad_esu_hr*/
                                var hromEsuContent = $.content(this.element.find('.js-hrom-esu'));
                                zmena = hromEsuContent.isChanged();
                                break;
                        }
                    }
                    return zmena;
