                function ProvazatFormulare(content) {
                    content.on("vfpprovestalg", function (ev, ctx) {
                        const form = content.findForms("FormFinancovani");
                        if (ev.target != form.get(0)) {
                            form.trigger(ev.type, ctx);
                        }
                    });
                }
                PrefabsVfp.ProvazatFormulare = ProvazatFormulare;
