                //---------------------------------------------------------------------
                function algKontrola(priznak, ixs_pri, hodnNova, hodnPuvodni, rezim, that, hodnota3) {
                    hodnNova = Decimal.abs(hodnNova);
                    var pocetCyklu = 1;
                    if (priznak == "E") {
                        if (rezim == 3)
                            hodnNova = hodnNova.minus(hodnPuvodni);
                        pocetCyklu = 6;
                    }
                    else if (priznak == "C")
                        pocetCyklu = 3;
                    var ixs_esu = that.findForms("FormSubjekt").findFields("ixs_esu").gfield("getValue").ixs_esu;
                    var defstart = $.Deferred();
                    var defcurr;
                    for (let i = 0; i < pocetCyklu; i++) {
                        let prevPromise = i === 0 ? defstart : defcurr;
                        defcurr = prevPromise.then(function (result) {
                            return that.isl.VfpDetailDT.algKontrola({
                                hodnota1: hodnNova, /* doplní se z formuláře hromEsu*/
                                hodnota2: hodnPuvodni,
                                priznak: priznak,
                                rezim: rezim,
                                ixs_pri: ixs_pri,
                                ixs_esu: ixs_esu,
                                hodnota3: hodnota3,
                                anoDotaz: result
                            }).getData().then(function (retVal) {
                                if (!retVal.ok) {
                                    if (retVal.dotaz != "") {
                                        return Vfp.WebClient.PrefabsVfp.dotaz(retVal.hlavicka, retVal.dotaz, that)
                                            .then(function () {
                                            if (priznak == "E" || priznak == "C") {
                                                var anoDotaz = parseInt(retVal.castka.toString());
                                                return $.Deferred().resolve(anoDotaz).promise();
                                            }
                                            else {
                                                return $.Deferred().reject("OK").promise(); // spravna situace, kdy se nechci znovu dotazovat serveru
                                            }
                                        }, function () {
                                            return $.Deferred().reject().promise();
                                        });
                                    }
                                    else {
                                        that.dialogs.warning(retVal.hlavicka, retVal.hlas);
                                        return $.Deferred().reject().promise();
                                    }
                                }
                                else {
                                    return $.Deferred().reject("OK").promise(); // spravna situace, kdy se nechci znovu dotazovat serveru
                                }
                            });
                        });
                    }
                    defstart.resolve(0);
                    return defcurr.then(() => {
                        return $.Deferred().resolve().promise();
                    }, (reason) => {
                        if (reason === "OK") {
                            return $.Deferred().resolve().promise();
                        }
                        else {
                            return $.Deferred().reject().promise();
                        }
                    }).promise();
                }
                PrefabsVfp.algKontrola = algKontrola;
