        var tmp = $("<div class='gform--view-mode'>").appendTo(currentElement)
            .gform("setup", { layoutDescriptor: "L1M1S1, breaks-300-400" }).
            gformsection("create").gpidbar({ pid: dto.ixs_pri }).
            gformsection("create")
            .gformrow("addFieldsRow", "jres:26600049").gformtext(dto.ac_ag === null || dto.ac_ag === undefined ? "" : dto.ac_ag, "bold") //RC 26600049 : Agendové číslo
            .gformrow("addFieldsRow", "jres:26600050").gformtext(dto.ac === null || dto.ac === undefined ? "" : dto.ac, "bold") //RC 26600050 : Evidenční číslo
