                vratData() {
                    var seznam = this.grid.ggrid("getSelection");
                    var blok = [];
                    for (var i = 0, I = seznam.length; i < I; i++) {
                        blok.push({
                            identifikator: seznam[i].ixs_pri, cislo: null, cisloDec: null, datum: null,
                            stav: seznam[i].s_dgr, ac: seznam[i].ac, ac_ag: seznam[i].ac_ag, nazev: seznam[i].nazev,
                            stav_txt: seznam[i].s_dgr_txt, vlastnik: seznam[i].vlastnik_nazev, ixp_den: seznam[i].ixp_den, vlastnikIdent: seznam[i].vlastnikIdent
                        });
                    }
                    return blok;
                }
