                //---------------------------------------------------------------------
                obnovSeznam() {
                    var that = this;
                    if (this.refreshData)
                        this.view.requestData();
                    this.srvMenu.call("NastavMenu", { ixs_pri: that.ixs_pri }).then((ap) => {
                        that.ap = ap;
                        that.nastavTlacitka();
                    }).always(() => that.endOperation());
                }
                //---------------------------------------------------------------------
                akcePodani(ele) {
                    var that = this;
                    var row = this.grid.ggrid("activeRow");
                    Gordic.Vfp.Dialogs.GVfpPodani(this, { genIxp: this.genIxp, ixp: null, ktg_typ: row.ktg_typ, ele: false, ixs_krk: null, modOkna: "new", ixs_pri: row.ixs_pri, allDok: false, ac_ag: row.ac_ag, soutez: row.typ_dgr, ixs_esu: "", por_cis_nab: -1, novyDT: false })
                        .then(function (retval) {
                        var detailContent = that.navigate("Gordic.Vfp.WebClient.GVfpDetail", {
                            taskId: that.task_id,
                            uid: "GVfpDetail#",
                            ixp: retval.ixp, ktg_typ: retval.ktg_typ, ele: false, ixs_krk: retval.ixs_krk, modOkna: "newEdit", ixs_pri: retval.ixs_pri, podaniOut: false, allDok: true, ac_ag: null, soutez: retval.soutez, ixs_esu: "", por_cis_nab: retval.por_cis_nab
                        });
                        detailContent.on("close", function (ev, ctx) {
                            if (ev.target === detailContent.get(0) && ctx && ctx.isChanged) {
                                var focusFunc = function () {
                                    if (that.grid.hasClass('ggrid')) {
                                        that.grid.ggrid('focus'); // nastavení focusu na grid
                                        that.view.off('change.focus', focusFunc); // odvázání události z ISL view
                                    }
                                };
                                that.view.on('change.focus', focusFunc);
                                that.obnovSeznam();
                            }
                            else
                                detailContent.one('closed', function () { if (that.grid.hasClass('ggrid'))
                                    that.grid.ggrid('focus'); });
                        });
                    });
                }
                //---------------------------------------------------------------------
                getOpenDetailDelegate() {
                    var that = this;
                    var seznam = this.view.getDataRows();
                    return (cnt, grid, row) => {
                        //   var rowSez: Interface.VfpspidDto = seznam.find(it => it.ixp === row.identifikator) ?? {};
                        var rowSez = {};
                        for (let i = 0, ii = seznam.length; i < ii; i++) {
                            if (seznam[i].ixp === row.identifikator) {
                                rowSez = seznam[i];
                                break;
                            }
                        }
                        let gridRC = new Gordic.Components.GridRC(grid); //pohyb po gridu
                        var detailContent = cnt.navigate(["Gordic.Vfp.WebClient.GVfpDetail", {
                                gridRemoteControl: gridRC
                            }], {
                            taskId: that.task_id,
                            uid: "GVfpDetail#",
                            ixs_pri: rowSez.ixs_pri, modOkna: "edit", ele: false, ixp: rowSez.ixp, ixs_krk: rowSez.ixs_krk, ktg_typ: rowSez.ktg_typ, ac_ag: rowSez.ac_ag, allDok: false, soutez: rowSez.typ_dgr, ixs_esu: "", por_cis_nab: -1
                        });
                    };
                }
                //---------------------------------------------------------------------
                getOpenDetailDelegateVfp() {
                    var that = this;
                    var seznam = this.view.getDataRows();
                    return (cnt, grid, row) => {
                        let gridRC = new Gordic.Components.GridRC(grid); //pohyb po gridu
                        var detailContent = cnt.navigate(["Gordic.Vfp.WebClient.GVfpDetail", {
                                gridRemoteControl: gridRC
                            }], {
                            taskId: that.task_id,
                            uid: "GVfpDetail#",
                            ixs_pri: row.ixs_pri, modOkna: "edit", ele: false, ixp: row.ixp, ixs_krk: row.ixs_krk, ktg_typ: row.ktg_typ, ac_ag: row.ac_ag, allDok: false, soutez: row.typ_dgr, ixs_esu: "", por_cis_nab: -1
                        });
                    };
                }
                //---------------------------------------------------------------------
                akceDetail() {
                    var that = this;
                    var row = this.grid.ggrid("activeRow");
                    var mod = row.vfp_stav == 10 ? "newEdit" : "edit";
                    var detailContent = this.navigate(["Gordic.Vfp.WebClient.GVfpDetail", {
                            gridRemoteControl: new Gordic.Components.GridRC(that.grid)
                        }], {
                        taskId: that.task_id,
                        uid: "GVfpDetail#",
                        ixs_pri: row.ixs_pri, modOkna: mod, ele: false, ixp: row.ixp, ixs_krk: row.ixs_krk, ktg_typ: row.ktg_typ, ac_ag: row.ac_ag, allDok: false, soutez: row.typ_dgr, ixs_esu: "", por_cis_nab: -1
                    }); //zobrazeni dalsiho detailu - stejne okno
                    detailContent.on("close", function (ev, ctx) {
                        if (ev.target === detailContent.get(0) && ctx && ctx.isChanged) {
                            var focusFunc = function () {
                                if (that.grid.hasClass('ggrid')) {
                                    that.grid.ggrid('focus'); // nastavení focusu na grid
                                    that.view.off('change.focus', focusFunc); // odvázání události z ISL view
                                }
                            };
                            that.view.on('change.focus', focusFunc);
                            that.isChanged = true;
                            that.obnovSeznam();
                        }
                        else
                            detailContent.one('closed', function () { if (that.grid.hasClass('ggrid'))
                                that.grid.ggrid('focus'); });
                    });
                }
                //---------------------------------------------------------------------
                akceSchvalitPis(storno) {
                    var that = this;
                    var blok = this.grid.ggrid("getSelection");
                    this.dotaz("jres:26600552", storno ? "jres:26600721" : "jres:26600722") //RC 26600722 : Opravdu chcete hromadné schválení označených dokumentů?
                        .then(function () {
                        Gordic.Vfp.WebClient.VfpPrefabsAll.SchvalitPis({
                            parentContent: that,
                            data: that.grid.ggrid("getSelection"),
                            zrusit: storno,
                            completeDelegate: (view) => {
                                that.obnovSeznam();
                            },
                            allDok: false,
                            openDetailDelegate: that.getOpenDetailDelegateVfp()
                        });
                    });
                }
