                dotaz(otazka) {
                    return this.dialogs.confirm(otazka).createDialogPromise("yes");
                }
                //---------------------------------------------------------------------
                doplneni() {
                    var that = this;
                    var seznam = this.grid.ggrid("getSelection");
                    var def0 = $.Deferred();
                    if (seznam.length > 50) {
                        var l_doplText = seznam.length > 500 ? "jres:26600974" : ""; //RC 26600974 : Maximálně lze provést doplnění u 500 záznamů.
                        that.dotaz("jres:26600969".replace("{0}", seznam.length.toString()).replace("{1}", l_doplText)) //RC 26600969 : Bylo celkem vybráno {0} záznamů. Tato akce je časově náročná. {1};; Chcete pokračovat?
                            .then(() => {
                            def0.resolve(true);
                        })
                            .fail(function () { def0.resolve(false); });
                    }
                    else
                        def0.resolve(true);
                    def0.then(function () {
                        that.beginOperation();
                        that.isl.VfpUchazeci.doplnOkrSml({ list: seznam }).getData().then(function (data) {
                            if (that.grid.hasClass('ggrid')) {
                                that.grid.ggrid("getView").updateData(data);
                                that.dialogs.warning("jres:26600972", "jres:26600973"); //RC 26600973 : Vybrané záznamy byly doplněny.
                            }
                        })
                            .always(() => that.endOperation());
                    });
                }
                //---------------------------------------------------------------------
                nastavTlacitka() {
                    var enabled = false;
                    enabled = this.view.getCount("filter") > 0;
                    if (this.typ != "subj") {
                        var vlastnik = false;
                        if (enabled) {
                            if (this.grid.hasClass('ggrid')) {
                                var row = this.grid.ggrid("activeRow");
                                if (row)
                                    vlastnik = row.vlastnik;
                            }
                        }
                        this.actions.actPodani.enabled(enabled /*&& this.ap.podani!*/ && (vlastnik || this.paramReaucz == "1") && !this.sumarRegi);
                        this.actions.actUkony.enabled(enabled /*&& this.ap.podani!*/ && !this.sumarRegi);
                        //  this.actions.actPodaniEl!.enabled(enabled /*&& this.ap.podaniel!*/);
                    }
                    if (this.typ != "regi") {
                        this.actions.actSpravaVyh.enabled(enabled);
                        this.actions.actSpravaNevyh.enabled(enabled);
                        this.actions.actDetail.enabled(enabled);
                    }
                    if (this.typ == "ucha") {
                        this.actions.actDoplneni.enabled(enabled);
                    }
                }
