                //---------------------------------------------------------------------
                sprava(vyhodnocenych) {
                    var that = this;
                    var l_ktgTyp = vyhodnocenych === true ? 2081 : 2071;
                    var l_label = vyhodnocenych === true ? "jres:26600851" : "jres:26600860";
                    var seznam = that.grid.ggrid("getSelection");
                    // nastavit s_ess
                    that.isl.VfpUchazeci.nastavEss({ ktg_typ: l_ktgTyp }).get().then(function (retVal) {
                        if (retVal.data.ok) {
                            Gordic.Vfp.WebClient.VfpPrefabsAll.SpravaStavuCastek({
                                parentContent: that,
                                label: l_label,
                                ktg_typ: l_ktgTyp,
                                data: that.UpravVyber(seznam),
                                completeDelegate: (view) => {
                                    that.obnovSeznam();
                                },
                            });
                        }
                    });
                }
                //---------------------------------------------------------------------
                UpravVyber(seznam) {
                    var l_seznam = [];
                    for (var i = 0; i < seznam.length; i++) {
                        if (seznam[i].vlastnik || this.paramPricpr)
                            l_seznam.push(seznam[i]);
                    }
                    return l_seznam;
                }
                //---------------------------------------------------------------------
                obnovSeznam() {
                    if (this.refreshData)
                        this.view.requestData();
                }
                //---------------------------------------------------------------------
                showComparison(rows) {
                    var that = this;
                    if (rows.length > 0) {
                        var dataRows = rows.map(function (item, idx) { return item.data; }); // převod z grid metadata-view do pole dto
                        if (this.isComparisonInited) {
                            this.addToComparison(dataRows);
                        }
                        else {
                            this.isComparisonInited = true;
                            this.comparisonCnt.empty();
                            this.comparator = $('<div class="js-comparator">').appendTo(this.comparisonCnt).gcomparator({
                                items: dataRows,
                                columns: that.grid.ggrid("option", "columns"),
                                itemTemplate: "{ixp}",
                                itemchange: function (ev, ctx) {
                                    that.comparisonBadge.value = ctx.count.toString();
                                    that.comparisonBadge.update();
                                },
                                selection: function (ev, ctx) {
                                    that.grid.ggrid("activeRow", ctx.item);
                                }
                            });
                        }
                        for (var row in rows) {
                            rows[row].checked = false;
                        }
                        this.grid.ggrid("refresh");
                    }
                }
                //---------------------------------------------------------------------
                addToComparison(rows) {
                    this.comparator.gcomparator("addItems", rows);
                }
