                //---------------------------------------------------------------------
                obnovSeznam() {
                    if (this.refreshData)
                        this.view.requestData();
                }
                //---------------------------------------------------------------------
                akcePodani(ele) {
                    var that = this;
                    var row = this.grid.ggrid("activeRow");
                    Gordic.Vfp.Dialogs.GVfpPodani(this, { genIxp: this.genIxp, ixp: null, ktg_typ: row.ktg_typ, ele: false, ixs_krk: null, modOkna: "new", ixs_pri: row.ixs_pri, allDok: false, ac_ag: row.ac_ag, soutez: row.typ_dgr, ixs_esu: that.ixs_esu, por_cis_nab: -1, novyDT: false })
                        .then(function (retval) {
                        var detailContent = that.navigate("Gordic.Vfp.WebClient.GVfpDetail", {
                            //                      taskId: "actGVfpSeznamScr",
                            uid: "GVfpDetail#",
                            ixp: retval.ixp, ktg_typ: retval.ktg_typ, ele: false, ixs_krk: retval.ixs_krk, modOkna: "newEdit", ixs_pri: retval.ixs_pri, podaniOut: false, allDok: true, ac_ag: null, soutez: retval.soutez, ixs_esu: that.ixs_esu, por_cis_nab: retval.por_cis_nab
                        });
                        detailContent.on("close", function (ev, ctx) {
                            if (ev.target === detailContent.get(0) && ctx && ctx.isChanged) {
                                var focusFunc = function () {
                                    if (that.grid.hasClass('ggrid')) {
                                        that.grid.ggrid('focus'); // nastavení focusu na grid
                                        that.view.off('change.focus', focusFunc); // odvázání události z ISL view
                                    }
                                };
                                that.view.on('change.focus', focusFunc);
                                that.obnovSeznam();
                            }
                            else
                                detailContent.one('closed', function () { if (that.grid.hasClass('ggrid'))
                                    that.grid.ggrid('focus'); });
                        });
                    });
                }
                //---------------------------------------------------------------------
                akceDetail() {
                    var that = this;
                    var row = this.grid.ggrid("activeRow");
                    var detailContent = this.navigate(["Gordic.Vfp.WebClient.GVfpDetail", {
                            gridRemoteControl: new Gordic.Components.GridRC(that.grid)
                        }], {
                        //                   taskId: "actGVfpSeznamScr",
                        uid: "GVfpDetail#",
                        ixs_pri: row.ixs_pri, modOkna: "edit", ele: false, ixp: row.ixp, ixs_krk: row.ixs_krk, ktg_typ: row.ktg_typ, ac_ag: row.ac_ag, allDok: false, soutez: row.typ_dgr, ixs_esu: that.ixs_esu, por_cis_nab: -1
                    }); //zobrazeni dalsiho detailu - stejne okno
                    detailContent.on("close", function (ev, ctx) {
                        if (ev.target === detailContent.get(0) && ctx && ctx.isChanged) {
                            var focusFunc = function () {
                                if (that.grid.hasClass('ggrid')) {
                                    that.grid.ggrid('focus'); // nastavení focusu na grid
                                    that.view.off('change.focus', focusFunc); // odvázání události z ISL view
                                }
                            };
                            that.view.on('change.focus', focusFunc);
                            that.isChanged = true;
                            that.obnovSeznam();
                        }
                        else
                            detailContent.one('closed', function () { if (that.grid.hasClass('ggrid'))
                                that.grid.ggrid('focus'); });
                    });
                }
