                akcePredvyhodn() {
                    var radek = this.grid.ggrid("getSelection")[0];
                    var that = this;
                    var dlg = Gordic.Vfp.Dialogs.GPredvyhodnoceniScr(this, {
                        ixs_pri: radek.ixs_pri,
                        paramRcZobr: that.paramRcZobr
                    }, Gordic.Gin.Globals.Enums.ModOtevreni.showWindow)
                        .then(function (retVal) {
                        if (retVal.isChanged) {
                            that.isChanged = true;
                            that.obnovSeznam();
                        }
                    });
                }
