                //---------------------------------------------------------------------
                nastavTlacitka() {
                    var that = this;
                    var enabled = false;
                    enabled = this.view.getCount("filter") > 0;
                    var def0 = $.Deferred();
                    if (enabled) {
                        var row = this.grid.ggrid("activeRow");
                        if (row && row.ixs_pri != that.ixsPriSave) {
                            that.call("NastavPrava", { ixs_pri: row.ixs_pri }).then(function (data) {
                                def0.resolve(data);
                            });
                        }
                        else
                            def0.reject();
                    }
                    else
                        def0.reject();
                    def0.then(function (ap) {
                        that.ixsPriSave = row.ixs_pri;
                        that.actions.actPodani.update({ enabled: enabled && ap.podani });
                        that.actions.actPodaniEl.update({ enabled: enabled && ap.podaniel });
                        that.actions.actDetail.update({ enabled: enabled && ap.detail });
                        that.actions.actSchvalitPis.update({ enabled: enabled && ap.schvalit });
                        that.actions.actOdSchvalitPis.update({ enabled: enabled && ap.schvalit });
                        that.actions.actPredvyhodn.update({ enabled: enabled && ap.predvyhodnoceni });
                        that.actions.actNavrhy.update({ enabled: enabled && ap.predvyhodnoceni });
                        // this.actions.actLokality!.update({ enabled: this.ap. /*nevím*/ });
                        //this.actions.actPVPP!.update({ enabled: enabled && this.ap.predani_pis! });
                        //this.actions.actPAllVPP!.update({ enabled: enabled && this.ap.predani_vlapis! });
                        //this.actions.actPAllPP!.update({ enabled: enabled && this.ap.predani! });
                        that.actions.actPreevidence.update({ enabled: enabled && ap.preevid_esu });
                        that.actions.actZmenaSubjDok.update({ enabled: enabled && ap.zamen_esu });
                        that.actions.actUkonceni.update({ enabled: enabled && ap.ukonceni });
                        that.actions.actZrusitUkonceni.update({ enabled: enabled && ap.ukonceni_zrus });
                        that.actions.actStornoPis.update({ enabled: enabled && ap.stornopis });
                        that.actions.actStornoPisZrus.update({ enabled: enabled && ap.stornopis });
                        //this.actions.actGenDok!.update({ enabled: enabled /*nevím*/ });
                        that.actions.actTisky.update({ enabled: enabled });
                    });
                }
